import requests

session = requests.Session()
session.headers.update({
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
})

# Try spring-haru/pwtdata repo
urls = [
    'https://raw.githubusercontent.com/spring-haru/pwtdata/main/data/pwt1001.xlsx',
    'https://raw.githubusercontent.com/spring-haru/pwtdata/master/data/pwt1001.xlsx',
    'https://github.com/spring-haru/pwtdata/raw/main/data/pwt1001.xlsx',
    'https://github.com/spring-haru/pwtdata/raw/master/data/pwt1001.xlsx',
]

for url in urls:
    print(f'Trying: {url}')
    try:
        resp = session.get(url, timeout=15, allow_redirects=True)
        print(f'  Status: {resp.status_code}, Size: {len(resp.content)} bytes')
        if resp.status_code == 200 and len(resp.content) > 50000:
            fname = '/root/pwt_data.xlsx'
            with open(fname, 'wb') as f:
                f.write(resp.content)
            print(f'  Saved as {fname}')
            if resp.content[:4] == b'PK\x03\x04':
                print('  Valid Excel file!')
                break
    except Exception as e:
        print(f'  Error: {e}')

# List repo contents via GitHub API
print('\nListing spring-haru/pwtdata repo contents...')
try:
    resp = session.get('https://api.github.com/repos/spring-haru/pwtdata/contents/', timeout=15)
    if resp.status_code == 200:
        for item in resp.json():
            print(f'  {item["name"]} ({item["type"]})')
except Exception as e:
    print(f'  Error: {e}')

