import requests

session = requests.Session()
session.headers.update({
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
})

# Explore pwtdata directory
print('Exploring pwtdata directory...')
resp = session.get('https://api.github.com/repos/spring-haru/pwtdata/contents/pwtdata', timeout=15)
if resp.status_code == 200:
    for item in resp.json():
        print(f'  {item["name"]} ({item["type"]}) - {item.get("download_url", "")}')
        if item['type'] == 'dir':
            resp2 = session.get(item['url'], timeout=15)
            if resp2.status_code == 200:
                for subitem in resp2.json():
                    print(f'    {subitem["name"]} ({subitem["type"]}) - {subitem.get("download_url", "")}')

